// === Tab: mySketch ===
/*
	particles
	a very simple and poorly coded (probably) sketch about particles.
	my first ever sketch :D
*/

// trail dot
class Dot {

  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.prevX = this.x;
    this.prevY = this.y;
  }

  move(x, y) {
    this.prevX = this.x;
    this.prevY = this.y;
    this.x += x;
    this.y += y;
  }
}

// particle
class Particle {

  constructor(pos, vel, r, col) {
    this.pos = pos;
    this.vel = vel;
    this.r = r;
    this.life = 255;
    this.col = col;
  }

  update() {
    this.pos.add(this.vel);
    this.life -= decay;
    this.vel.mult(0.99);
  }

  draw() {
    noStroke();
    this.col.setAlpha(this.life);
    fill(this.col);
    circle(this.pos.x, this.pos.y, this.r * 2);
  }
}

// EDITABLES
const radius = 1,								// size of particles
      trailLength = 25,					// length of trail
      trailStiffness = 0.9,			// stiffness of trail (0.5 - 0.9 -> short n quick, 0.1 - 0.5 -> long n slooooow)
      angleNoise = 10,					// direction randomness of particles emitted
      decay = 5,								// how fast particles lose their life and fade away
			particlesSpawned = 10,		// amount of particles to spawn every frame update when going sufficiently fast
      speedThreshold = 5,				// how fast the cursor has to go to emit particles
      minSpeedMultiplier = 0.1,	// slwoest a particle can go relative to the speed of the cursor
      maxSpeedMultiplier = 0.5;	// fastest a particle can go relative to the speed of the cursor

let dots = [],
    particles = [];

function setup() {
  createCanvas(windowWidth, windowHeight);
  noStroke();
  angleMode(DEGREES);

	// add trail dots
  for (let i = 0; i < trailLength; i++) {
    dots.push(new Dot(
      0,
      0
    ));
  }
}

function draw() {
  background(0, 127);

	// move the first trail dot
  dots[0].move(
    ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - dots[0].x) * trailStiffness,
    ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - dots[0].y) * trailStiffness
  );

	// move the rest of the trail dots
  for (let i = 1; i < dots.length; i++) {
    dots[i].move(
      (dots[i - 1].prevX - dots[i].x) * trailStiffness,
      (dots[i - 1].prevY - dots[i].y) * trailStiffness
    );
  }

	// draw trail
  fill(255); // edit this if you're bored of white
  beginShape(TRIANGLE_STRIP);
  vertex((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));

  for (let i = 0; i < dots.length; i++) {
    vertex(
      dots[i].prevX,
      dots[i].prevY
    );
  }

  endShape();

	// spawn particles
  let movement = sqrt(movedX ** 2 + movedY ** 2);
  for (let i = 0; i < particlesSpawned; i++) {
		if (movement < speedThreshold) break;
    let angle = atan2(movedY, movedX) + random(-angleNoise, angleNoise),
        speed = random(minSpeedMultiplier, maxSpeedMultiplier) * movement;

    particles.push(new Particle(
      createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))),
      createVector(cos(angle) * speed, sin(angle) * speed),
      radius,
      color(255, 255, 255) // edit this if you're bored of white
    ));
  }

	// move and kill particles
  for (let i = particles.length - 1; i >= 0; i--) {
		let particle = particles[i];
    particle.update();
    particle.draw();
    if (particle.life < 0 || particle.pos.x < -radius || particle.pos.x > width + radius || particle.pos.y < -radius || particle.pos.y > height + radius)
			particles.splice(i, 1);
  }
}

